-- ~/.config/hypr/binds.lua — Omarchy-style keybinds (generated by Waterbear). Cheat sheet: Super+K.
-- Laid out like Omarchy's bindings, using Waterbear's tools (rofi, kitty, Thunar, swaync).
-- Add or change binds in ~/.config/hypr/user.lua, not here.

local mainMod  = "SUPER"
local terminal = "kitty"
local browser  = "firefox"
local files    = "thunar"
local bin      = "~/.local/bin/"
local menu     = "kitty --class waterbear-menu -e waterbear"

local function key(combo) return mainMod .. " + " .. combo end
local function tui(cmd) return terminal .. " -e " .. cmd end

---------------
---- APPS -----
---------------
hl.bind(key("Return"),               hl.dsp.exec_cmd(terminal))
hl.bind(key("ALT + Return"),         hl.dsp.exec_cmd(terminal .. " bash -c 'tmux attach || tmux new -s Work'"))
hl.bind(key("SHIFT + Return"),       hl.dsp.exec_cmd(browser))
hl.bind(key("SHIFT + B"),            hl.dsp.exec_cmd(browser))
hl.bind(key("SHIFT + ALT + B"),      hl.dsp.exec_cmd(browser .. " --private-window"))
hl.bind(key("SHIFT + F"),            hl.dsp.exec_cmd(files))
hl.bind(key("SHIFT + N"),            hl.dsp.exec_cmd(tui("nvim")))                      -- editor
hl.bind(key("SHIFT + M"),            hl.dsp.exec_cmd("spotify"))                         -- music
hl.bind(key("SHIFT + D"),            hl.dsp.exec_cmd(tui("lazydocker")))                 -- Docker
hl.bind(key("SHIFT + G"),            hl.dsp.exec_cmd("signal-desktop"))
hl.bind(key("SHIFT + O"),            hl.dsp.exec_cmd("obsidian"))
hl.bind(key("CTRL + T"),             hl.dsp.exec_cmd(tui("btop")))                       -- activity

----------------
---- MENUS -----
----------------
hl.bind(key("space"),                hl.dsp.exec_cmd("pkill -x rofi || rofi -show drun"))   -- launch apps
hl.bind(key("CTRL + E"),             hl.dsp.exec_cmd("pkill -x rofi || rofi -modi emoji -show emoji"))
hl.bind(key("CTRL + V"),             hl.dsp.exec_cmd(bin .. "clipboard.sh"))            -- clipboard history
hl.bind(key("K"),                    hl.dsp.exec_cmd("kitty --class keyhelp -e waterbear shortcuts"))
hl.bind(key("Escape"),               hl.dsp.exec_cmd(bin .. "powermenu.sh"))            -- system menu
hl.bind("XF86PowerOff",              hl.dsp.exec_cmd(bin .. "powermenu.sh"), { locked = true })
hl.bind(key("CTRL + space"),         hl.dsp.exec_cmd(menu .. " background"))            -- background menu
hl.bind(key("SHIFT + CTRL + space"), hl.dsp.exec_cmd(menu .. " theme"))                 -- theme menu
hl.bind(key("SHIFT + space"),        hl.dsp.exec_cmd("pkill -SIGUSR1 -x waybar || " .. bin .. "waterbear-bar"))  -- toggle top bar

-----------------------
---- NOTIFICATIONS ----
-----------------------
hl.bind(key("comma"),                hl.dsp.exec_cmd("swaync-client --close-latest"))   -- dismiss last
hl.bind(key("SHIFT + comma"),        hl.dsp.exec_cmd("swaync-client --close-all"))      -- dismiss all
hl.bind(key("CTRL + comma"),         hl.dsp.exec_cmd("swaync-client --toggle-dnd"))     -- silence
hl.bind(key("CTRL + N"),             hl.dsp.exec_cmd("pkill -x hyprsunset || hyprsunset -t 4500"))  -- night light
hl.bind(key("CTRL + ALT + T"),       hl.dsp.exec_cmd([[notify-send -u low "$(date +'%A %H:%M · %d %B %Y · Week %V')"]]))
hl.bind(key("CTRL + ALT + B"),       hl.dsp.exec_cmd(bin .. "status.sh"))               -- battery / wifi / volume

-----------------
---- WINDOWS ----
-----------------
hl.bind(key("W"),          hl.dsp.window.close())
hl.bind(key("J"),          hl.dsp.layout("togglesplit"))
hl.bind(key("P"),          hl.dsp.window.pseudo())
hl.bind(key("T"),          hl.dsp.window.float({ action = "toggle" }))
hl.bind(key("F"),          hl.dsp.window.fullscreen({ mode = "fullscreen" }))
hl.bind(key("ALT + F"),    hl.dsp.window.fullscreen({ mode = "maximized" }))            -- full width

local dirs = { left = "left", right = "right", up = "up", down = "down" }
for arrow, dir in pairs(dirs) do
    hl.bind(key(arrow),              hl.dsp.focus({ direction = dir }))
    hl.bind(key("SHIFT + " .. arrow), hl.dsp.window.swap({ direction = dir }))
end

-- Resize: Super + minus / equal (wider / narrower), with Shift for height
hl.bind(key("minus"),         hl.dsp.window.resize({ x = -100, y = 0, relative = true }), { repeating = true })
hl.bind(key("equal"),         hl.dsp.window.resize({ x =  100, y = 0, relative = true }), { repeating = true })
hl.bind(key("SHIFT + minus"), hl.dsp.window.resize({ x = 0, y = -100, relative = true }), { repeating = true })
hl.bind(key("SHIFT + equal"), hl.dsp.window.resize({ x = 0, y =  100, relative = true }), { repeating = true })

-- Mouse: Super + left-drag moves, Super + right-drag resizes
hl.bind(key("mouse:272"), hl.dsp.window.drag(),   { mouse = true })
hl.bind(key("mouse:273"), hl.dsp.window.resize(), { mouse = true })

-- Alt+Tab cycles windows and raises the one it lands on
hl.bind("ALT + Tab", function()
    hl.dispatch(hl.dsp.window.cycle_next())
    hl.dispatch(hl.dsp.window.alter_zorder({ mode = "top" }))
end)

-- Groups
hl.bind(key("G"),         hl.dsp.group.toggle())
hl.bind(key("ALT + Tab"), hl.dsp.group.next())

--------------------
---- WORKSPACES ----
--------------------
for i = 1, 10 do
    local k = i % 10   -- workspace 10 is on the 0 key
    hl.bind(key(k),                    hl.dsp.focus({ workspace = i }))
    hl.bind(key("SHIFT + " .. k),       hl.dsp.window.move({ workspace = i, follow = true }))
    hl.bind(key("SHIFT + ALT + " .. k), hl.dsp.window.move({ workspace = i, follow = false }))   -- silently
end

hl.bind(key("Tab"),         hl.dsp.focus({ workspace = "e+1" }))
hl.bind(key("SHIFT + Tab"), hl.dsp.focus({ workspace = "e-1" }))
hl.bind(key("CTRL + Tab"),  hl.dsp.focus({ workspace = "previous" }))
hl.bind(key("mouse_down"),  hl.dsp.focus({ workspace = "e+1" }))
hl.bind(key("mouse_up"),    hl.dsp.focus({ workspace = "e-1" }))

-- Scratchpad
hl.bind(key("S"),         hl.dsp.workspace.toggle_special("scratchpad"))
hl.bind(key("ALT + S"),   hl.dsp.window.move({ workspace = "special:scratchpad", follow = false }))

---------------------
---- SCREENSHOTS ----
---------------------
hl.bind("Print",              hl.dsp.exec_cmd(bin .. "screenshot.sh area"))
hl.bind("SHIFT + Print",      hl.dsp.exec_cmd(bin .. "screenshot.sh full"))
hl.bind("ALT + Print",        hl.dsp.exec_cmd(bin .. "screenshot.sh window"))
hl.bind(key("Print"),         hl.dsp.exec_cmd(bin .. "screenshot.sh edit"))      -- area → swappy

----------------
---- SYSTEM ----
----------------
hl.bind(key("CTRL + L"),      hl.dsp.exec_cmd("pidof hyprlock || hyprlock"))

-- Media / volume / brightness keys
hl.bind("XF86AudioRaiseVolume",  hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume",  hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),      { locked = true, repeating = true })
hl.bind("XF86AudioMute",         hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),     { locked = true })
hl.bind("XF86AudioMicMute",      hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),   { locked = true })
hl.bind("XF86MonBrightnessUp",   hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%+"),                  { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%-"),                  { locked = true, repeating = true })
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"),       { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { locked = true })
